#usda 1.0
(
    defaultPrim = "World"
    documentation = "SpatialDSL model layout only; asset and physics opinions live in sibling layers."
    metersPerUnit = 1
    timeCodesPerSecond = 60
    upAxis = "Z"
)

def Xform "World"
{
    custom string spatialDsl:layerRole = "layout"

    def Cube "Floor"
    {
        float size = 1
        color3f[] primvars:displayColor = [(0.18, 0.20, 0.23)]
        double3 xformOp:scale = (80, 60, 0.1)
        double3 xformOp:translate = (5, 0, -0.05)
        uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:scale"]
    }

    def Xform "MobileRobot"
    {
{{#each elementsByClassName.MobileRobot}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "MobileRobot"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, 0)
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ"]
        }
{{/each}}
    }

    def Xform "Conveyor"
    {
{{#each elementsByClassName.Conveyor}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "Conveyor"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }

    def Xform "OutputLocation"
    {
{{#each elementsByClassName.OutputLocation}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "OutputLocation"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }

    def Xform "ChargingStation"
    {
{{#each elementsByClassName.ChargingStation}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "ChargingStation"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }

    def Xform "PathwayArea"
    {
{{#each elementsByClassName.PathwayArea}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "PathwayArea"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }

    def Xform "StorageRack"
    {
{{#each elementsByClassName.StorageRack}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "StorageRack"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }

    def Xform "Dock"
    {
{{#each elementsByClassName.Dock}}
        def Xform "{{usdIdentifier name}}_{{@index}}"
        {
            custom string spatialDsl:className = "Dock"
            custom string spatialDsl:sourceName = "{{name}}"
            double3 xformOp:translate = ({{meters X}}, {{meters Y}}, {{halfMeters Height}})
            float xformOp:rotateZ = {{#unless RZ}}0{{else}}{{RZ}}{{/unless}}
            double3 xformOp:scale = ({{meters Length}}, {{meters Width}}, {{meters Height}})
            uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateZ", "xformOp:scale"]
        }
{{/each}}
    }
}

#usda 1.0
(
    defaultPrim = "World"
    documentation = "Asset references only. Paths are relative to the generated bundle root."
    metersPerUnit = 1
    timeCodesPerSecond = 60
    upAxis = "Z"
)

def Xform "World"
{
    custom string spatialDsl:layerRole = "assets"

    over "MobileRobot"
    {
{{#each elementsByClassName.MobileRobot}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/nvidia-f1tenth-amr/f1tenth_amr_collision.usda@
        )
        {
            custom string spatialDsl:assetMode = "collision"
            custom string spatialDsl:articulationAsset = "omniverse-assets/nvidia-f1tenth-amr/f1tenth_amr_articulation.usda"
        }
{{/each}}
    }

    over "Conveyor"
    {
{{#each elementsByClassName.Conveyor}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/conveyor.usda@
        ) {}
{{/each}}
    }

    over "OutputLocation"
    {
{{#each elementsByClassName.OutputLocation}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/output_location.usda@
        ) {}
{{/each}}
    }

    over "ChargingStation"
    {
{{#each elementsByClassName.ChargingStation}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/charging_station.usda@
        ) {}
{{/each}}
    }

    over "PathwayArea"
    {
{{#each elementsByClassName.PathwayArea}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/pathway_area.usda@
        ) {}
{{/each}}
    }

    over "StorageRack"
    {
{{#each elementsByClassName.StorageRack}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/storage_rack.usda@
        ) {}
{{/each}}
    }

    over "Dock"
    {
{{#each elementsByClassName.Dock}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend references = @omniverse-assets/warehouse-kit/dock.usda@
        ) {}
{{/each}}
    }
}

#usda 1.0
(
    defaultPrim = "World"
    documentation = "PhysX scene, static proxy colliders, and kinematic robot-body defaults."
    metersPerUnit = 1
    timeCodesPerSecond = 60
    upAxis = "Z"
)

def Xform "World"
{
    custom string spatialDsl:layerRole = "physics"

    def PhysicsScene "PhysicsScene"
    {
        vector3f physics:gravityDirection = (0, 0, -1)
        float physics:gravityMagnitude = 9.81
    }

    def Scope "PhysicsMaterials"
    {
        def Material "WarehouseDefault" (
            prepend apiSchemas = ["PhysicsMaterialAPI"]
        )
        {
            float physics:staticFriction = 0.72
            float physics:dynamicFriction = 0.58
            float physics:restitution = 0.05
        }
    }

    over "Floor" (
        prepend apiSchemas = ["PhysicsCollisionAPI"]
    )
    {
        rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
    }

    over "MobileRobot"
    {
{{#each elementsByClassName.MobileRobot}}
        over "{{usdIdentifier name}}_{{@index}}" (
            prepend apiSchemas = ["PhysicsRigidBodyAPI", "PhysicsMassAPI"]
        )
        {
            bool physics:kinematicEnabled = true
            bool physics:rigidBodyEnabled = true
            float physics:mass = 3.1
            custom string spatialDsl:bodyMode = "kinematic"
            custom string spatialDsl:dynamicControl = "velocity"
        }
{{/each}}
    }

    over "Conveyor"
    {
{{#each elementsByClassName.Conveyor}}
        over "{{usdIdentifier name}}_{{@index}}"
        {
            def Cube "PhysicsProxy" (
                prepend apiSchemas = ["PhysicsCollisionAPI"]
            )
            {
                float size = 1
                uniform token purpose = "guide"
                token visibility = "invisible"
                rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
            }
        }
{{/each}}
    }

    over "OutputLocation"
    {
{{#each elementsByClassName.OutputLocation}}
        over "{{usdIdentifier name}}_{{@index}}"
        {
            def Cube "PhysicsProxy" (
                prepend apiSchemas = ["PhysicsCollisionAPI"]
            )
            {
                float size = 1
                uniform token purpose = "guide"
                token visibility = "invisible"
                rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
            }
        }
{{/each}}
    }

    over "ChargingStation"
    {
{{#each elementsByClassName.ChargingStation}}
        over "{{usdIdentifier name}}_{{@index}}"
        {
            def Cube "PhysicsProxy" (
                prepend apiSchemas = ["PhysicsCollisionAPI"]
            )
            {
                float size = 1
                uniform token purpose = "guide"
                token visibility = "invisible"
                rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
            }
        }
{{/each}}
    }

    over "StorageRack"
    {
{{#each elementsByClassName.StorageRack}}
        over "{{usdIdentifier name}}_{{@index}}"
        {
            def Cube "PhysicsProxy" (
                prepend apiSchemas = ["PhysicsCollisionAPI"]
            )
            {
                float size = 1
                uniform token purpose = "guide"
                token visibility = "invisible"
                rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
            }
        }
{{/each}}
    }

    over "Dock"
    {
{{#each elementsByClassName.Dock}}
        over "{{usdIdentifier name}}_{{@index}}"
        {
            def Cube "PhysicsProxy" (
                prepend apiSchemas = ["PhysicsCollisionAPI"]
            )
            {
                float size = 1
                uniform token purpose = "guide"
                token visibility = "invisible"
                rel physics:material:binding = </World/PhysicsMaterials/WarehouseDefault>
            }
        }
{{/each}}
    }
}
